import json
rows=[json.loads(l) for l in open("agent-a2fa1fcd6089ef4ee.jsonl") if l.strip()]
def walk(o, kind):
    if isinstance(o, dict):
        if o.get("type")==kind: yield o
        for v in o.values(): yield from walk(v, kind)
    elif isinstance(o, list):
        for v in o: yield from walk(v, kind)
for i in (128, 167, 195):
    for tu in walk(rows[i], "tool_use"):
        if tu.get("name")=="Bash":
            print(f"===== row {i} {str(rows[i].get('timestamp',''))[11:19]} COMMAND =====")
            print(tu["input"].get("command","")[:3000])
def result_text(r):
    out=[]
    for tr in walk(r, "tool_result"):
        c=tr.get("content")
        if isinstance(c, list):
            for b in c:
                if isinstance(b, dict) and b.get("type")=="text": out.append(b["text"])
        elif isinstance(c, str): out.append(c)
    return "\n".join(out)
for i in (129,130,131,132,133, 168,169,170,171,172,173,174,175,176, 196,197):
    t=result_text(rows[i])
    if t.strip():
        print(f"===== row {i} {str(rows[i].get('timestamp',''))[11:19]} RESULT =====")
        print(t[:2500])
